/**
 * Region `tayvallich`, "Tayvallich and Loch Sween": the second region made from real map
 * data by the coast pipeline (tools/coast; docs/COAST_PIPELINE.md): Tayvallich and its bay,
 * Caol Scotnish with the Fairy Isles at its head, Loch Sween from its mouth by Castle Sween to
 * Achnamara, the Taynish peninsula, and the Sound of Jura shore by Carsaig and Keills, at
 * full scale (11.2 x 15.6 km). Its data is the pipeline's package (tayvallich.coast.json,
 * regenerated by `npm run build tayvallich` in tools/coast); its ground is the package's
 * mesh, fetched at start.
 *
 * Where: the coast region test (regions/index.ts) puts it in place of the Sounds, north of
 * home like Oban: the channel from its south edge up to Loch Sween's mouth north of Calder
 * Haven (the Sound of Jura's open water to the west of it). It covers where the Fjord lies, which is left
 * out while it's on; the Narrows stay, to the west.
 *
 * OpenStreetMap has no buoys or lights mapped here: none in the region yet.
 */
import type { CoastPackage } from '../coastRegion';
import { fromCoastPackage } from '../coastRegion';
import { SOUNDS } from './sounds';
import pkg from './tayvallich.coast.json';

export const TAYVALLICH = fromCoastPackage(pkg as unknown as CoastPackage, {
  // The package's origin (the box's centre) in the world: the channel from the box's south
  // edge to Loch Sween's mouth (about x -3100 in the package) north of Calder Haven (x 570),
  // the south edge at z -1900 where the Sounds' was (its box runs to z 7786 in the package).
  x: 3670,
  z: -9686,
  weather: SOUNDS.weather,
});
